// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    EtherLotto c;

    function setUp() public {
        c = new EtherLotto();
    }

    receive() external payable {}

    function testFuzz_property(uint256 ts, uint256 diff, address actor) public {
        vm.assume(ts < type(uint64).max);
        vm.assume(actor != address(0) && actor != address(this));
        vm.assume(uint160(actor) > 10);

        vm.warp(ts);
        vm.roll(diff);

        vm.deal(actor, 10);
        vm.prank(actor);
        c.play{value: 10}();

        uint256 random = uint256(keccak256(abi.encodePacked(ts, block.difficulty, actor))) % 2;

        // General rule: whenever the draw is a win (random % 2 == 0), the pot
        // MUST be fully paid out and reset to 0 after play(). The mutant uses
        // % 3 and skips the payout for even draws not divisible by 3,
        // leaving pot == 10 in those cases.
        if (random == 0) {
            assertTrue(c.pot() == 0, "winning play must reset the pot to 0");
        } else {
            assertTrue(c.pot() == 10, "losing play must accumulate exactly one ticket");
        }
    }
}
